// Add the salon email here when ready. A mail application opens with the request;
// use a server email provider later for reliable automatic delivery.
const SALON_EMAIL = '';
const booking = document.querySelector('#booking-dialog');
const form = document.querySelector('#booking-form');
let draft = '';
const toast = message => {const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)};
const bangkokToday = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
document.querySelector('#date').min=bangkokToday();
document.querySelector('#year').textContent=new Date().getFullYear();
if(SALON_EMAIL){document.querySelector('.notice').textContent='This form opens your email application with your appointment request. Your preferred time is subject to confirmation by the salon.';form.querySelector('[type=submit]').innerHTML='Prepare booking email <span>↗</span>';form.querySelector('.consent').lastChild.textContent=' I understand my preferred appointment is subject to salon confirmation.';document.querySelector('.booking-banner small').textContent='Appointments are confirmed by the salon by email.';}
document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#date').min=bangkokToday();form.hidden=false;document.querySelector('#draft-result').hidden=true;const value=button.dataset.book;if(value)document.querySelector('#service').value=value;booking.showModal()}));
document.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}}));
booking.addEventListener('close',()=>{form.reset();draft='';document.querySelector('#draft-summary').textContent='';form.hidden=false;document.querySelector('#draft-result').hidden=true});
form.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(data.date<bangkokToday()){document.querySelector('#date').setCustomValidity('Please choose today or a future date.');document.querySelector('#date').reportValidity();return}draft=`KANNIKA — APPOINTMENT REQUEST DRAFT\n\nTreatment: ${data.service}\nPreferred date: ${data.date}\nPreferred time: ${data.time} (Pattaya, Thailand)\nName: ${data.name}\nEmail: ${data.email}\nNotes: ${data.notes || '—'}\n\nThis is a draft. No appointment has been sent or confirmed.`;if(SALON_EMAIL){window.location.href=`mailto:${encodeURIComponent(SALON_EMAIL)}?subject=${encodeURIComponent('Kannika appointment request')}&body=${encodeURIComponent(draft.replace('This is a draft. No appointment has been sent or confirmed.','Please confirm availability for this request.'))}`;toast('Your email app will open. Send the email to request your visit.');return}document.querySelector('#draft-summary').textContent=`${data.service} · ${data.date} · ${data.time} (Pattaya time)`;form.hidden=true;document.querySelector('#draft-result').hidden=false;document.querySelector('#draft-result h3').setAttribute('tabindex','-1');document.querySelector('#draft-result h3').focus()});
document.querySelector('#date').addEventListener('input',event=>event.target.setCustomValidity(''));
document.querySelector('#edit-draft').addEventListener('click',()=>{form.hidden=false;document.querySelector('#draft-result').hidden=true;document.querySelector('#service').focus()});
document.querySelector('#download-draft').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([draft],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='kannika-appointment-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your appointment draft has been downloaded')});
let sharedTitle='';let sharedURL='';
document.querySelectorAll('[data-share]').forEach(button=>button.addEventListener('click',()=>{sharedURL=new URL('#'+button.dataset.share,window.location.href).href;sharedTitle=button.dataset.title+' | Kannika';document.querySelector('#share-title').textContent=button.dataset.title;document.querySelector('#share-url').value=sharedURL;document.querySelector('#share-facebook').href='https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(sharedURL);document.querySelector('#share-whatsapp').href='https://wa.me/?text='+encodeURIComponent(sharedTitle+' '+sharedURL);document.querySelector('#share-line').href='https://social-plugins.line.me/lineit/share?url='+encodeURIComponent(sharedURL);document.querySelector('#native-share').hidden=!navigator.share;document.querySelector('#share-dialog').showModal()}));
document.querySelector('#native-share').addEventListener('click',async()=>{try{await navigator.share({title:sharedTitle,url:sharedURL})}catch(error){if(error.name!=='AbortError')toast('Use Copy story link to share this story.')}});
document.querySelector('#copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(sharedURL);toast('Story link copied')}catch{document.querySelector('#share-url').select();toast('Select and copy the story link above')}});
document.querySelector('#privacy-button').addEventListener('click',()=>document.querySelector('#privacy-dialog').showModal());
document.querySelector('.menu-toggle').addEventListener('click',event=>{const open=document.querySelector('nav').classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open));event.currentTarget.setAttribute('aria-label',open?'Close menu':'Open menu')});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}));
